# -*- coding: utf-8 -*-
from ._helpers import intro, schema, fall, mc

KURS = dict(
    id="u08", gebiet="upc", titel="Kosten, Gebühren und Prozesskostensicherheit",
    untertitel="Gerichtsgebühren und Streitwert, Kostengrundentscheidung und Kostenfestsetzung, Sicherheit für die Kosten des Beklagten",
    farbe="#0f766e", icon="tabelle",
    beschreibung="Das Geld hinter dem Verfahren: Festgebühr und streitwertabhängige Gebühr nach R. 370 VerfO, Ermäßigung und Erstattung (Juul/NJOY, Roku/Dolby), der Streitwert nach R. 370.6 (Kodak/Fujifilm), die Kostengrundentscheidung nach Art. 69 EPGÜ mit Obergrenzen (SharkNinja, Strabag/Swarco), die Kostenfestsetzung nach R. 150 bis 157 mit ihrer Monatsfrist, die Kosten bei Erledigung nach R. 360 (Dolby/Roku) und die Prozesskostensicherheit nach Art. 69 Abs. 4 EPGÜ, R. 158 VerfO in der Linie Aarke/SodaStream, Hefei/Grundfos, Syntorr/Arthrex, La Siddhi/Athena und Suinno/Microsoft.",
    kapitel=[
        dict(id="u08a", titel="Gerichtsgebühren und Streitwert (R. 370 VerfO)", einheiten=[
            schema("u08a-0", "Prüfungsschema: Kosten, Gebühren und Prozesskostensicherheit", "upc_schema_kosten",
                   "Vier Stationen: die Gerichtsgebühren bei Einreichung (R. 370), die Sicherheit für die Kosten des Beklagten während des Verfahrens (Art. 69 Abs. 4, R. 158), die Kostengrundentscheidung im Urteil (Art. 69 Abs. 1 bis 3, R. 118.5) und die Kostenfestsetzung danach (R. 150 bis 157). Die Obergrenzen der erstattungsfähigen Vertretungskosten hängen am Streitwert (R. 152.2)."),
            mc("u08a-1", "Das Gebührensystem der R. 370 VerfO",
                "Welche Aussage zu den Gerichtsgebühren trifft zu?",
                ["Norvex zahlt eine Festgebühr und zusätzlich eine streitwertabhängige Gebühr, und zwar nur einmal, obwohl die Klage zwei Patente und drei Beklagte betrifft.",
                 "Norvex zahlt je Patent und je Beklagtem eine eigene Festgebühr, die streitwertabhängige Gebühr fällt nur einmal an.",
                 "Für die Widerklage auf Nichtigerklärung fällt keine Gebühr an, weil sie ein Verteidigungsmittel gegen die Verletzungsklage ist.",
                 "Nimmt Norvex die Klage nach der Zwischenanhörung zurück, erhält sie stets die Hälfte der Gerichtsgebühren zurück."],
                0,
                ["**Richtig ist die erste Aussage.** Für die Verletzungsklage ist eine **Festgebühr** zu entrichten (R. 370.2 lit. a VerfO) und, weil der Streitwert 500.000 EUR übersteigt, zusätzlich eine **streitwertabhängige Gebühr** (R. 370.3 VerfO) nach der Gebührentabelle des Verwaltungsausschusses. Betrifft die Klage mehrere Kläger, mehrere Beklagte oder mehrere Patente, ist nach R. 370.7 VerfO gleichwohl **nur eine** Festgebühr und gegebenenfalls eine streitwertabhängige Gebühr zu zahlen. Die zweite Aussage ist deshalb falsch.",
                 "Die dritte Aussage ist falsch: Auch die Widerklage auf Nichtigerklärung ist gebührenpflichtig (R. 370.4 lit. b VerfO); die Nichtigkeitsklage vor der Zentralkammer ebenso (lit. a). Die vierte Aussage ist falsch: Die Erstattung von 50 % bei Rücknahme setzt voraus, dass die Klage **vor Abschluss des schriftlichen Verfahrens** zurückgenommen wird (R. 370.9 lit. b VerfO in der seit 1.1.2026 geltenden Fassung; EPG-BerG Juul/NJOY); nach der Zwischenanhörung gibt es keine Erstattung mehr, und in außergewöhnlichen Fällen kann das Gericht sie ohnehin kürzen (R. 370.9 lit. e). Kleine Unternehmen und Kleinstunternehmen zahlen ermäßigte Gebühren, wenn sie die Erklärung nach R. 370.8 VerfO abgeben; gefährden die Gebühren die wirtschaftliche Existenz, kommt die Erstattung nach R. 370.10 in Betracht."],
                sachverhalt="Die Klägerin Norvex erhebt Verletzungsklage aus zwei Patenten gegen drei Beklagte; das Gericht setzt den Streitwert auf 2 Mio. EUR fest. Die Beklagten erheben Widerklage auf Nichtigerklärung.",
                merke="Festgebühr plus Streitwertgebühr ab 500.000 EUR – einmal je Klage, gleich wie viele Patente und Beklagte (R. 370.7).",
                level=2, concepts=["upc_gerichtsgebuehren", "upc_ruecknahme"], norms=["R. 370.2 VerfO", "R. 370.3 VerfO", "R. 370.7 VerfO", "R. 370.9 VerfO"],
                cases=["upc_coa_juul_njoy_gebuehren"], step="step:upc_schema_kosten.1"),
            fall("u08a-2", "Vier Berufungen, eine Gebühr?",
                 "Roku ist in vier parallelen Verletzungsverfahren von Dolby verklagt worden und hat in jedem Verfahren mit demselben Einspruch die Zuständigkeit des EPG gerügt. Die Lokalkammer weist alle vier Einsprüche mit gleichlautender Begründung zurück und lässt die Berufung zu. Roku legt vier Berufungen ein, zahlt aber nur eine Berufungsgebühr: Die Rechtsfrage sei identisch, das Berufungsgericht werde ohnehin gemeinsam verhandeln, eine Vervierfachung der Gebühr sei unverhältnismäßig.",
                 "Genügt eine Berufungsgebühr für die vier Berufungen?", False,
                 ["**Nein!** Die Berufungsgebühr ist nach R. 370.5 VerfO i.V.m. R. 228 VerfO **für jedes Berufungsverfahren** zu entrichten. Jede Berufung richtet sich gegen eine eigene Entscheidung in einem eigenen Verfahren mit eigenem Aktenzeichen; dass die zu entscheidenden Fragen gleich sind, ändert an der Zahl der Verfahren nichts (EPG-BerG Roku/Dolby). Die gemeinsame Verhandlung nach R. 220.5 VerfO ist eine Frage der Verfahrensleitung, keine der Gebühr.",
                  "Die Gebührentabelle kennt für den Fall mehrerer Patente oder Parteien **innerhalb einer Klage** die Privilegierung der R. 370.7 VerfO; mehrere Klagen bleiben mehrere Klagen. Wird die Gebühr nicht innerhalb der von der Kanzlei gesetzten Frist gezahlt, gilt die Berufung als nicht eingelegt (R. 228 VerfO). Roku muss die drei fehlenden Gebühren nachentrichten."],
                 merke="Je Berufungsverfahren eine Gebühr – auch wenn die Frage immer dieselbe ist.",
                 level=1, concepts=["upc_gerichtsgebuehren", "upc_berufung"], norms=["R. 370.5 VerfO", "R. 228 VerfO", "R. 220.5 VerfO"],
                 cases=["upc_coa_roku_dolby_einspruch"], step="step:upc_schema_kosten.1"),
            fall("u08a-3", "Der Streitwert der Vollstreckung",
                 "Gegen Kodak sind wegen Verstößen gegen eine Unterlassungsanordnung Zwangsgelder von 300.000 EUR festgesetzt worden. Kodak greift die Festsetzung an. Für die Gebühr und die Kostenobergrenze ist der Streitwert festzusetzen. Fujifilm, die die Vollstreckung betreibt, will den Streitwert mit 300.000 EUR ansetzen: Das sei der Betrag, um den es Kodak gehe.",
                 "Ist der Streitwert nach der Summe der verfallenen Zwangsgelder zu bemessen?", False,
                 ["**Nein!** Der Streitwert muss nach R. 370.6 VerfO das **objektive Interesse der Partei widerspiegeln, die das Verfahren eingeleitet hat**, im Zeitpunkt der Einleitung. Im Vollstreckungsverfahren ist das das Interesse des Vollstreckungsgläubigers Fujifilm an der Befolgung der Unterlassungsanordnung, nicht das Abwehrinteresse des Schuldners.",
                  "Die verfallenen Zwangsgelder sind kein Maßstab, weil sie nach Art. 82 Abs. 4 EPGÜ, R. 354.3 VerfO **an das Gericht** fließen und nicht an Fujifilm; sie messen die Beugewirkung, nicht das wirtschaftliche Interesse an der Unterlassung (EPG-BerG Kodak/Fujifilm 2026). Der Streitwert kann sich an dem Interesse orientieren, das der Unterlassungsanordnung selbst zugrunde liegt, gegebenenfalls anteilig für den durchgesetzten Teil. Die Streitwertfestsetzung ist eine Verfahrensentscheidung, gegen die nur der Weg über R. 220.2, 220.3 VerfO offensteht, auch wenn sie im Tenor steht."],
                 merke="R. 370.6: Streitwert = Interesse dessen, der das Verfahren eingeleitet hat; Zwangsgelder zählen nicht, sie gehören dem Gericht.",
                 level=3, concepts=["upc_streitwert", "upc_zwangsgeld"], norms=["R. 370.6 VerfO", "Art. 82 Abs. 4 EPGÜ", "R. 354.3 VerfO"],
                 cases=["upc_coa_kodak_fujifilm_aufhebung_zwangsgeld"], step="step:upc_schema_kosten.1"),
        ]),
        dict(id="u08b", titel="Kostengrundentscheidung und Kostenfestsetzung (Art. 69 EPGÜ, R. 150 bis 157 VerfO)", einheiten=[
            intro("u08b-0", "Wer zahlt, wie viel, und in welchem Verfahren",
                  "Art. 69 Abs. 1 EPGÜ enthält den Grundsatz: Die Kosten des Rechtsstreits und sonstigen Kosten der **obsiegenden Partei** trägt in der Regel die unterlegene Partei, soweit sie **zumutbar und angemessen** sind und **bis zu einer Obergrenze**, die der Verwaltungsausschuss nach dem Streitwert festlegt (R. 152.2 VerfO), sofern Billigkeitsgründe nicht entgegenstehen. Bei teilweisem Obsiegen oder außergewöhnlichen Umständen verteilt das Gericht die Kosten nach Billigkeit oder lässt jede Partei ihre Kosten tragen (Abs. 2); wer unnötige Kosten verursacht, soll sie tragen (Abs. 3). Das Gericht entscheidet in der Sachentscheidung **dem Grunde nach** über die Kostentragung (R. 118.5 VerfO) und kann eine vorläufige Kostenerstattung zusprechen (R. 150.2 VerfO). Die **Höhe** wird in einem gesonderten Verfahren festgesetzt: Antrag der obsiegenden Partei **binnen eines Monats** nach der Entscheidung mit Angabe der Kosten (R. 151 VerfO), Anhörung der Gegenseite, Entscheidung des Berichterstatters (R. 156 VerfO); erstattungsfähig sind die Gerichtsgebühren, die angemessenen und verhältnismäßigen Kosten der Vertretung (R. 152), Kosten für Zeugen und Sachverständige (R. 153, 154) und sonstige Ausgaben. Zwei Feinheiten aus der Rechtsprechung: Bei zwei Patenten und Erfolg nur mit einem sind die Kosten nach den Werten der Patente zu verteilen (EPG-BerG SharkNinja); der Streithelfer wird kostenrechtlich wie die Hauptpartei behandelt (EPG-BerG Strabag/Swarco). Erledigt sich das Verfahren, entscheidet das Gericht nach R. 360 VerfO über die Kosten danach, ob der Beklagte Anlass zur Klage gegeben hat. Art. 69 setzt Art. 14 DurchsetzungsRL um; das deutsche Pendant sind §§ 91 ff. ZPO mit der Streitwertbegünstigung des § 144 PatG.",
                  concepts=["upc_kostenerstattung", "upc_streithilfe"], norms=["Art. 69 Abs. 1 EPGÜ", "Art. 69 Abs. 2 EPGÜ", "R. 118.5 VerfO", "R. 152 VerfO"],
                  cases=["upc_coa_strabag_swarco_streithilfe"]),
            fall("u08b-1", "Zwei Patente, ein Sieg",
                 "SharkNinja wird aus zwei Patenten verklagt. Das Gericht bejaht die Verletzung von Patent A und verurteilt SharkNinja zur Unterlassung; die Klage aus Patent B, das den weit größeren Teil des Streitwerts ausmacht, wird abgewiesen, weil das Patent auf die Widerklage widerrufen wird. Die Klägerin beantragt, SharkNinja die gesamten Kosten aufzuerlegen: Sie sei im Ergebnis mit dem Unterlassungsantrag durchgedrungen, mehr habe sie nie gewollt.",
                 "Muss SharkNinja die gesamten Kosten des Verfahrens tragen?", False,
                 ["**Nein!** Obsiegt eine Partei nur teilweise, kann das Gericht nach Art. 69 Abs. 2 EPGÜ anordnen, dass die Kosten **nach Billigkeit verteilt** werden. Die Klage aus Patent B ist abgewiesen und das Patent widerrufen; insoweit ist die Klägerin unterlegen, auch wenn sie das Unterlassungsziel über Patent A erreicht hat. Der Umfang des Obsiegens bemisst sich nach den Streitgegenständen, nicht nach dem wirtschaftlichen Endergebnis.",
                  "Sind zwei Patente Gegenstand des Verfahrens und hat die Klage nur bei einem Erfolg, ist es in der Regel angemessen, die Kosten **im Verhältnis der Werte der beiden Patente** zu verteilen; alternativ kann das Gericht jeder Partei die dem jeweiligen Patent zuzuordnenden Kosten auferlegen (EPG-BerG SharkNinja). Da Patent B den größeren Teil des Streitwerts ausmacht, trägt die Klägerin den größeren Teil der Kosten. Die Verteilung gilt auch für die Kosten der Widerklage, mit der SharkNinja obsiegt hat."],
                 merke="Teilweises Obsiegen bei zwei Patenten: Kosten nach dem Wertverhältnis der Patente, nicht nach dem Unterlassungserfolg.",
                 level=2, concepts=["upc_kostenerstattung"], norms=["Art. 69 Abs. 2 EPGÜ", "R. 118.5 VerfO", "R. 150 VerfO"],
                 cases=["upc_coa_sharkninja_kosten"], step="step:upc_schema_kosten.3"),
            fall("u08b-2", "Ohne Abmahnung in die Erledigung",
                 "Dolby beantragt gegen Roku ohne vorherige Abmahnung einstweilige Maßnahmen wegen eines Patents für Videocodierung. Nach Zustellung des Antrags gibt Roku eine strafbewehrte Unterlassungsverpflichtung ab; beide Parteien erklären das Verfahren für erledigt und beantragen die Einstellung nach R. 360 VerfO. Dolby meint, Roku müsse die Kosten tragen, weil der Antrag bei Einreichung zulässig und begründet war; Roku meint, ohne Abmahnung sei der Antrag schon unzulässig gewesen, jedenfalls habe sie keinen Anlass gegeben.",
                 "Kann das Fehlen der Abmahnung dazu führen, dass Dolby die Kosten des erledigten Verfahrens trägt?", True,
                 ["**Ja!** Bei Erledigung der Hauptsache entscheidet das Gericht nach R. 360 VerfO über die Kosten nach den Umständen; maßgeblich ist, ob der Beklagte **Anlass zur Klage** gegeben hat, beurteilt aus der **objektiven Sicht einer Person in der Lage des Klägers bei Einreichung** (LK München Dolby/Roku). Hat Roku erst durch den Antrag von der Verletzung erfahren und sich sofort unterworfen, hat sie keinen Anlass gegeben; dann können die Kosten Dolby auferlegt werden.",
                  "Roku hat dagegen unrecht, soweit sie den Antrag für unzulässig hält: Eine Abmahnung ist **keine Voraussetzung** für Zulässigkeit oder Begründetheit eines Antrags auf einstweilige Maßnahmen, und ihr Fehlen lässt auch die Dringlichkeit nach R. 211.4 VerfO nicht entfallen. Ihre Bedeutung liegt allein in der Kostenfolge: Wer ohne Abmahnung vorgeht und sofortige Unterwerfung erntet, riskiert die Kosten. Das entspricht dem Gedanken des § 93 ZPO im deutschen Recht."],
                 merke="Abmahnung ist im EPG keine Zulässigkeitsvoraussetzung – aber wer sie weglässt, kann bei sofortiger Unterwerfung auf den Kosten sitzen bleiben (R. 360).",
                 level=2, concepts=["upc_ruecknahme", "upc_kostenerstattung", "upc_einstweilige_massnahmen"], norms=["R. 360 VerfO", "Art. 69 Abs. 2 EPGÜ", "Art. 62 EPGÜ"],
                 cases=["upc_cfi_dolby_roku_veranlassung"], step="step:upc_schema_kosten.3"),
            mc("u08b-3", "Die Kostenfestsetzung nach R. 150 bis 157 VerfO",
                "Welche Aussage zur Kostenfestsetzung trifft zu?",
                ["Ilion muss den Antrag auf Kostenfestsetzung binnen eines Monats nach der Entscheidung stellen; erstattet werden die angemessenen und verhältnismäßigen Vertretungskosten bis zur streitwertabhängigen Obergrenze.",
                 "Ilion kann die Kostenfestsetzung binnen eines Jahres beantragen, weil dieselbe Frist wie für den Schadensersatz gilt.",
                 "Ilion erhält die vollen 600.000 EUR erstattet, weil die Kostenentscheidung Tarsus alle Kosten auferlegt hat.",
                 "Über die Kostenfestsetzung entscheidet der Spruchkörper in einer weiteren mündlichen Verhandlung."],
                0,
                ["**Richtig ist die erste Aussage.** Die obsiegende Partei muss den Antrag auf Kostenfestsetzung **innerhalb eines Monats nach der Entscheidung** stellen (R. 151 VerfO) und darin die Kosten angeben, deren Erstattung sie begehrt. Erstattungsfähig sind die **angemessenen und verhältnismäßigen** Kosten der Vertretung (R. 152.1 VerfO) nur **bis zur Obergrenze** der Tabelle des Verwaltungsausschusses (R. 152.2 VerfO, Art. 69 Abs. 1 EPGÜ). Von 600.000 EUR bleiben also höchstens 400.000 EUR; eine Erhöhung der Obergrenze kommt nur in den in der Tabelle vorgesehenen Ausnahmefällen in Betracht.",
                 "Die Jahresfrist der zweiten Option gilt für den Antrag auf Festsetzung des Schadensersatzes (R. 126 VerfO), nicht für die Kosten. Die dritte Option verkennt die doppelte Grenze aus Angemessenheit und Obergrenze. Die vierte Option ist falsch: Über die Kostenfestsetzung entscheidet der **Berichterstatter** schriftlich nach Anhörung der unterlegenen Partei (R. 156 VerfO); gegen seine Entscheidung ist die Überprüfung durch den Spruchkörper und dann die Berufung mit Zulassung möglich (R. 157, R. 221 VerfO)."],
                sachverhalt="Die Lokalkammer hat die Beklagte Tarsus am 5. Mai zur Unterlassung verurteilt und ihr die Kosten des Rechtsstreits auferlegt. Die Klägerin Ilion hat Vertretungskosten von 600.000 EUR aufgewandt; die Obergrenze für den festgesetzten Streitwert liegt bei 400.000 EUR.",
                merke="Kostenfestsetzung: ein Monat, Berichterstatter, Obergrenze – die Kostenentscheidung im Urteil regelt nur den Grund.",
                level=2, concepts=["upc_kostenerstattung"], norms=["R. 151 VerfO", "R. 152 VerfO", "R. 156 VerfO", "Art. 69 Abs. 1 EPGÜ"],
                step="step:upc_schema_kosten.4"),
        ]),
        dict(id="u08c", titel="Prozesskostensicherheit (Art. 69 Abs. 4 EPGÜ, R. 158 VerfO)", einheiten=[
            intro("u08c-0", "Sicherheit für die Kosten des Beklagten",
                  "Art. 69 Abs. 4 EPGÜ erlaubt dem Gericht, auf Antrag des Beklagten anzuordnen, dass der **Antragsteller** für die Kosten des Beklagten, die er möglicherweise tragen muss, angemessene **Sicherheit** leistet – insbesondere in den Fällen der Art. 59 bis 62 EPGÜ. R. 158.1 VerfO gestattet den Antrag zu jedem Zeitpunkt des Verfahrens; das Gericht bestimmt Frist und Form (Hinterlegung oder Bankbürgschaft), gewährt zuvor rechtliches Gehör (R. 158.2) und weist darauf hin, dass bei Nichtleistung eine **Versäumnisentscheidung** nach R. 355 ergehen kann (R. 158.4, 158.5 VerfO). Die Anordnung ist mit Zulassung nach R. 220.2 VerfO anfechtbar (R. 158.3). Die Voraussetzungen hat das Berufungsgericht in einer Linie von Entscheidungen geschärft: Der Antragsteller muss darlegen, dass die Vermögensverhältnisse des Klägers die Erstattung gefährden oder die Vollstreckung einer Kostenentscheidung unmöglich oder unangemessen beschwerlich wäre (LK München Edwards/Meril; EPG-BerG Aarke/SodaStream); maßgeblich ist die finanzielle Lage des Klägers selbst, nicht seines Konzerns; Sicherheit kann nur **gegen den Antragsteller** des jeweiligen Rechtszugs angeordnet werden, in erster Instanz also nur gegen den Kläger, in der Berufung nur gegen den Berufungskläger (Hefei/Grundfos; Suinno/Microsoft); eine Prozessfinanzierungsversicherung ist zu berücksichtigen (Syntorr/Arthrex); der KMU-Status befreit nicht, kann aber die Höhe beeinflussen, die sich an der Obergrenze der erstattungsfähigen Kosten orientiert (La Siddhi/Athena). Die Vorschrift entspricht funktional § 110 ZPO, ist aber nicht auf Kläger aus Drittstaaten beschränkt.",
                  concepts=["upc_prozesskostensicherheit", "upc_versaeumnisentscheidung"], norms=["Art. 69 Abs. 4 EPGÜ", "R. 158 VerfO", "R. 158.5 VerfO", "R. 355 VerfO"],
                  cases=["upc_cfi_edwards_meril_cms"]),
            fall("u08c-1", "Der solvente Konzern",
                 "Aarke, eine schwedische Gesellschaft mit geringem Eigenkapital und Verlusten in den letzten Geschäftsjahren, klagt vor der Lokalkammer gegen SodaStream. SodaStream beantragt Prozesskostensicherheit. Aarke wendet ein, sie gehöre zu einem finanzstarken Konzern, der für sie einstehen werde; außerdem sei ihre Klage offensichtlich begründet, sodass eine Kostenerstattung ohnehin nicht drohe, und sie erkläre sich ausdrücklich bereit, etwaige Kosten zu erstatten.",
                 "Stehen Konzernzugehörigkeit, Erfolgsaussichten und Erstattungsbereitschaft der Anordnung entgegen?", False,
                 ["**Nein!** Für die Prozesskostensicherheit nach Art. 69 Abs. 4 EPGÜ, R. 158.1 VerfO ist **allein die finanzielle Lage des Klägers selbst** maßgeblich. Die Zugehörigkeit zu einem solventen Konzern hilft nicht, weil die Konzernmutter nicht Partei ist und ihre Bereitschaft, für Kosten der Tochter einzustehen, rechtlich nicht gesichert ist; ebenso unerheblich sind die bloße Bereitschaft des Klägers zur Erstattung und die **Erfolgsaussichten** der Klage, die im Sicherheitsverfahren nicht geprüft werden (EPG-BerG Aarke/SodaStream).",
                  "SodaStream muss allerdings darlegen, dass die Vermögensverhältnisse von Aarke die Erstattung gefährden oder dass die Vollstreckung einer Kostenentscheidung unmöglich oder **unangemessen beschwerlich** wäre; die Unmöglichkeit der Vollstreckung muss nicht bewiesen werden. Beruft sich der Antragsteller auf Vollstreckungshindernisse im Sitzstaat, muss er das dortige Recht und seine Anwendung darlegen; innerhalb der EU ist das wegen der Brüssel-Ia-VO selten erfolgreich, weshalb hier die schwache Vermögenslage von Aarke selbst den Ausschlag gibt. Das Gericht entscheidet nach Ermessen über Höhe, Frist und Form der Sicherheit (R. 158.1 VerfO)."],
                 merke="R. 158: Es zählt die Kasse des Klägers, nicht die des Konzerns – und die Erfolgsaussichten bleiben außen vor.",
                 level=2, concepts=["upc_prozesskostensicherheit"], norms=["Art. 69 Abs. 4 EPGÜ", "R. 158.1 VerfO"],
                 cases=["upc_coa_aarke_sodastream_sicherheit", "upc_cfi_edwards_meril_cms"], step="step:upc_schema_kosten.2"),
            fall("u08c-2", "Sicherheit gegen den Widerkläger?",
                 "Grundfos klagt gegen Hefei, eine chinesische Herstellerin, auf Unterlassung. Hefei erhebt Widerklage auf Nichtigerklärung. Grundfos beantragt, Hefei aufzugeben, Sicherheit für die Kosten der Widerklage zu leisten: Hefei sei mit der Widerklage Angreiferin, ihr Vermögen liege außerhalb der EU, und eine Kostenentscheidung wäre in China nur mit großem Aufwand vollstreckbar.",
                 "Ist der Antrag von Grundfos statthaft?", False,
                 ["**Nein!** Art. 69 Abs. 4 EPGÜ erlaubt die Anordnung von Sicherheit nur zu Lasten des **Antragstellers**, also desjenigen, der den Rechtszug in Gang bringt, und nur auf Antrag des **Beklagten**. In erster Instanz ist das der Kläger. Ein Antrag des Klägers gegen den Beklagten ist unstatthaft, auch wenn dieser Widerklage auf Nichtigerklärung erhebt: Die Widerklage ist die unmittelbare Folge der Verletzungsklage und macht den Beklagten nicht zum Antragsteller im Sinne des Art. 69 Abs. 4 (EPG-BerG Hefei/Grundfos; bestätigt in Suinno/Microsoft).",
                  "R. 158.1 VerfO spricht zwar allgemein von einem Antrag „einer Partei“ gegen „die andere Partei“, ist aber im Lichte des vorrangigen Übereinkommens auszulegen (Art. 41 Abs. 1 EPGÜ). Für die Berufung gilt dasselbe Prinzip spiegelbildlich: Antragsbefugt ist allein der Berufungsbeklagte, auch wenn er erstinstanzlich Kläger war; bei wechselseitigen Berufungen kann jede Partei nur Sicherheit für die Kosten der Berufung der anderen verlangen. Eine Ausnahme macht das Berufungsgericht, wenn der Beklagte zu Recht einen evidenten Fehler der erstinstanzlichen Entscheidung rügt: Dann kann nur er Sicherheit für die Berufungsinstanz verlangen."],
                 merke="Sicherheit nur gegen den, der den Rechtszug eröffnet: erstinstanzlich der Kläger, in der Berufung der Berufungskläger – nie der Widerkläger.",
                 level=3, concepts=["upc_prozesskostensicherheit", "upc_widerklage_nichtigkeit"], norms=["Art. 69 Abs. 4 EPGÜ", "R. 158.1 VerfO"],
                 cases=["upc_coa_hefei_grundfos_sicherheit", "upc_coa_suinno_microsoft_prozesskostensicherheit"], step="step:upc_schema_kosten.2"),
            mc("u08c-3", "Versicherung, KMU und die Höhe der Sicherheit",
                "Welche Aussage trifft zu?",
                ["Als Kleinunternehmen mit Erklärung nach R. 370.8 VerfO ist Syntorr von der Prozesskostensicherheit befreit.",
                 "Die Versicherung ist unbeachtlich, weil nur das eigene Vermögen des Klägers zählt.",
                 "Die Versicherung ist bei der Ermessensentscheidung zu berücksichtigen, ob eine berechtigte und reale Sorge besteht, dass eine Kostenentscheidung nicht vollstreckt werden kann; der KMU-Status befreit nicht, kann aber bei der Höhe einfließen.",
                 "Die Höhe der Sicherheit ist stets auf die Gerichtsgebühren beschränkt, die Syntorr bereits gezahlt hat."],
                2,
                ["**Richtig ist die dritte Aussage.** Die Anordnung nach Art. 69 Abs. 4 EPGÜ, R. 158.1 VerfO ist eine Ermessensentscheidung; zu prüfen ist, ob die finanzielle Lage des Klägers eine **berechtigte und reale Sorge** begründet, dass eine Kostenentscheidung nicht oder nur unangemessen beschwerlich vollstreckt werden kann. Eine **After-the-event-Versicherung**, die die Kosten des Beklagten deckt, mindert diese Sorge und ist zu berücksichtigen (EPG-BerG Syntorr/Arthrex); die zweite Aussage ist deshalb falsch. Entscheidend ist, dass der Beklagte auf die Deckung tatsächlich zugreifen kann (Bedingungen, Ausschlüsse, Kündbarkeit).",
                 "Die erste Aussage ist falsch: Die Eigenschaft als KMU oder eine Erklärung nach R. 370.8 VerfO **befreit nicht** von der Sicherheit, wenn deren Voraussetzungen vorliegen; die Gebührenermäßigung und die Sicherheit für die Kosten der Gegenseite haben verschiedene Zwecke (EPG-BerG La Siddhi/Athena). Die vierte Aussage ist falsch: Die **Höhe** bemisst sich ausgehend von der **Obergrenze der erstattungsfähigen Kosten** (Anhang A des Beschlusses des Verwaltungsausschusses vom 24.4.2023) nach allen Umständen; der KMU-Status kann dabei zu einer niedrigeren Sicherheit führen."],
                sachverhalt="Die Klägerin Syntorr, ein Kleinunternehmen mit Erklärung nach R. 370.8 VerfO, klagt gegen Arthrex. Arthrex beantragt Prozesskostensicherheit. Syntorr legt eine Prozessfinanzierungsversicherung (After-the-event-Versicherung) vor, die im Unterliegensfall die Kosten der Beklagten bis zur Obergrenze deckt.",
                merke="Versicherung mindert die Sorge, KMU-Status mindert allenfalls die Höhe – befreit ist niemand.",
                level=3, concepts=["upc_prozesskostensicherheit", "upc_gerichtsgebuehren"], norms=["Art. 69 Abs. 4 EPGÜ", "R. 158 VerfO", "R. 370.8 VerfO"],
                cases=["upc_coa_syntorr_arthrex_versicherung", "upc_coa_lasiddhi_athena_kmu"], step="step:upc_schema_kosten.2"),
            fall("u08c-4", "Die nicht geleistete Sicherheit",
                 "Suinno hat gegen Microsoft in erster Instanz verloren und Berufung eingelegt. Auf Antrag von Microsoft ordnet das Berufungsgericht an, dass Suinno binnen sechs Wochen Sicherheit für die Kosten der Berufung leistet, mit dem Hinweis nach R. 158.4 VerfO. Die Frist verstreicht ohne Zahlung. Microsoft beantragt eine Versäumnisentscheidung. Suinno wendet ein, sie sei als Klägerin des Ausgangsverfahrens durch R. 355.2 VerfO geschützt; eine Versäumnisentscheidung gegen den Kläger komme nur bei Untätigkeit trotz besonderer Aufforderung in Betracht.",
                 "Kann das Berufungsgericht die Versäumnisentscheidung gegen Suinno erlassen?", True,
                 ["**Ja!** Leistet eine Partei die angeordnete Sicherheit nicht innerhalb der gesetzten Frist, kann das Gericht eine Versäumnisentscheidung nach R. 355 VerfO erlassen (R. 158.5 VerfO); die Anordnung muss diese Folge angekündigt haben (R. 158.4), was hier geschehen ist. Für das Berufungsverfahren gilt der **Berufungskläger als Kläger** im Sinne der R. 355 VerfO. Der Schutz der R. 355.2 VerfO greift deshalb nicht, wenn der Berufungsbeklagte die Versäumnisentscheidung gegen den Berufungskläger beantragt, weil dieser eine Frist versäumt hat, etwa die angeordnete Sicherheit nicht geleistet hat oder nicht zur mündlichen Verhandlung erschienen ist (EPG-BerG Suinno/Microsoft).",
                  "Die Versäumnisentscheidung führt zur Zurückweisung der Berufung. Suinno kann binnen eines Monats nach Zustellung den Antrag auf Aufhebung stellen (R. 356 VerfO), muss dann aber die Gebühr entrichten und die Säumnis erklären. Ob Suinno als Berufungsklägerin überhaupt sicherheitspflichtig ist, steht nicht in Frage: Sicherheit wird gegen den Antragsteller des jeweiligen Rechtszugs angeordnet, in der Berufung also gegen den Berufungskläger, auch wenn er erstinstanzlich Kläger war (Hefei/Grundfos)."],
                 merke="Sicherheit nicht geleistet = Säumnis (R. 158.5); in der Berufung ist der Berufungskläger der Kläger, R. 355.2 schützt ihn nicht.",
                 level=3, concepts=["upc_prozesskostensicherheit", "upc_versaeumnisentscheidung"], norms=["R. 158.5 VerfO", "R. 355 VerfO", "R. 356 VerfO", "Art. 69 Abs. 4 EPGÜ"],
                 cases=["upc_coa_suinno_microsoft_versaeumnis", "upc_coa_hefei_grundfos_sicherheit"], step="step:upc_schema_kosten.2"),
        ]),
    ],
)
